components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: #111827;
  color: #ffffff;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-primary:hover { background: #374151; }
.ds-btn-primary:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.ds-btn-outline {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #ffffff;
  color: #374151;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), border-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-outline:hover { background: #f9fafb; border-color: #d1d5db; }
.ds-btn-outline:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }

.ds-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #4b5563;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-icon-btn:hover { background: #f3f4f6; color: #111827; }
.ds-icon-btn:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }
.ds-icon-btn:disabled { opacity: 0.4; cursor: not-allowed; }

.ds-chip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 2px 8px;
  border-radius: 9999px;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 400;
  line-height: 16px;
  white-space: nowrap;
}
.ds-chip-published { background: #ecfdf5; color: #047857; }

.ds-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: ui-sans-serif, system-ui, sans-serif;
}
.ds-field-label { color: #6b7280; font-size: 13px; font-weight: 500; line-height: 20px; }
.ds-input {
  box-sizing: border-box;
  width: 100%;
  height: 34px;
  padding: 6px 10px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #ffffff;
  color: #111827;
  font-family: inherit;
  font-size: 13px;
  line-height: 20px;
  outline: none;
  transition: border-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-input:focus { border-color: #9ca3af; }
.ds-input:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }
.ds-field-help { color: #6b7280; font-size: 12px; line-height: 16px; }

.ds-segmented {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: 32px;
  padding: 2px;
  border-radius: 8px;
  background: #f3f4f6;
}
.ds-segment {
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #4b5563;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-segment:hover { color: #111827; }
.ds-segment-active { background: #ffffff; color: #111827; box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05); }
.ds-segment:focus-visible { outline: 2px solid #4ccba0; outline-offset: 1px; }

.ds-card {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background: #ffffff;
  font-family: ui-sans-serif, system-ui, sans-serif;
  transition: border-color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-card:hover { border-color: #d1d5db; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1); }
.ds-card-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ds-card-title { margin: 0; color: #1f2937; font-size: 14px; font-weight: 600; line-height: 20px; }
.ds-card-status { border-radius: 9999px; background: #ecfdf5; color: #047857; font-size: 10px; line-height: 16px; padding: 2px 8px; white-space: nowrap; }
.ds-card-meta { margin: 0; color: #6b7280; font-size: 12px; line-height: 16px; }
.ds-card-actions { display: flex; align-items: center; justify-content: flex-end; gap: 4px; margin-top: 4px; }
.ds-card-link { box-sizing: border-box; height: 28px; padding: 0 10px; border: 1px solid #e5e7eb; border-radius: 8px; background: #ffffff; color: #6b7280; font-family: inherit; font-size: 12px; font-weight: 500; cursor: pointer; }
.ds-card-link:hover { background: #f9fafb; color: #111827; }
.ds-card-icon { width: 28px; height: 28px; border: 0; border-radius: 8px; background: transparent; color: #4b5563; font-size: 14px; cursor: pointer; }
.ds-card-icon:hover { background: #f3f4f6; color: #111827; }
.ds-card-link:focus-visible, .ds-card-icon:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }

.ds-composer {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border: 1px solid #e5e7eb;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  font-family: ui-sans-serif, system-ui, sans-serif;
  transition: border-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-composer:focus-within { border-color: #9ca3af; }
.ds-composer-input {
  width: 100%;
  min-height: 44px;
  padding: 2px 4px;
  border: 0;
  background: transparent;
  color: #111827;
  font-family: inherit;
  font-size: 13px;
  line-height: 24px;
  resize: none;
  outline: none;
}
.ds-composer-input::placeholder { color: #6b7280; }
.ds-composer-footer { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ds-composer-model {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: #f3f4f6;
  color: #4b5563;
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
}
.ds-composer-model:hover { color: #111827; }
.ds-composer-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: 9999px;
  background: #111827;
  color: #ffffff;
  cursor: pointer;
  transition: background-color 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-composer-send:hover { background: #374151; }
.ds-composer-model:focus-visible, .ds-composer-send:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }

.ds-inspector {
  box-sizing: border-box;
  width: 288px;
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  font-family: ui-sans-serif, system-ui, sans-serif;
}
.ds-inspector-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.ds-inspector-kicker { margin: 0 0 2px; color: #6b7280; font-size: 12px; line-height: 16px; }
.ds-inspector-title { margin: 0; color: #111827; font-size: 14px; font-weight: 600; line-height: 20px; }
.ds-inspector-close { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 0; border-radius: 8px; background: transparent; color: #4b5563; cursor: pointer; }
.ds-inspector-close:hover { background: #f3f4f6; color: #111827; }
.ds-inspector-path { margin: 4px 0 10px; color: #6b7280; font-family: monospace; font-size: 12px; line-height: 16px; }
.ds-inspector-field { display: flex; flex-direction: column; gap: 6px; color: #6b7280; font-size: 12px; font-weight: 500; line-height: 16px; }
.ds-inspector-field textarea { box-sizing: border-box; width: 100%; padding: 6px 10px; border: 1px solid #e5e7eb; border-radius: 8px; color: #111827; font-family: inherit; font-size: 13px; font-weight: 400; line-height: 20px; resize: vertical; outline: none; }
.ds-inspector-field textarea:focus { border-color: #9ca3af; }
.ds-inspector-field textarea:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }
.ds-inspector-actions { display: flex; justify-content: flex-end; gap: 6px; margin-top: 12px; }
.ds-inspector-cancel, .ds-inspector-apply { height: 28px; padding: 0 10px; border-radius: 8px; font-family: inherit; font-size: 12px; font-weight: 500; cursor: pointer; }
.ds-inspector-cancel { border: 0; background: transparent; color: #4b5563; }
.ds-inspector-cancel:hover { background: #f3f4f6; color: #111827; }
.ds-inspector-apply { border: 0; background: #111827; color: #ffffff; }
.ds-inspector-apply:hover { background: #374151; }
.ds-inspector-close:focus-visible, .ds-inspector-cancel:focus-visible, .ds-inspector-apply:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }

.ds-btn-console {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  padding: 0 16px;
  border: 0;
  border-radius: 4px;
  background: #0e1731;
  color: #ffffff;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 20px;
  cursor: pointer;
  transition: filter 150ms cubic-bezier(0.4, 0, 0.2, 1);
}
.ds-btn-console:hover { filter: brightness(1.15); }
.ds-btn-console:focus-visible { outline: 2px solid #4ccba0; outline-offset: 2px; }
